const pubs = $input.all().map((i) => i.json);
const qualified = pubs
  .filter((p) => {
    const email = p.contactEmail || p.substackReplyEmail || (Array.isArray(p.contactEmails) ? p.contactEmails[0] : '');
    const isPaid = Boolean(p.isPaid || Number(p.monthlyPriceUsd || 0) > 0 || /paid/i.test(String(p.rankingDetail || '')));
    return Boolean(email) && isPaid;
  })
  .map((p) => {
    const email = p.contactEmail || p.substackReplyEmail || (Array.isArray(p.contactEmails) ? p.contactEmails[0] : '');
    const postsText = JSON.stringify(p.latestPosts || p.recentPosts || []);
    const hasSponsorSignals = /sponsor|partner|advertis|newsletter|media kit/i.test(postsText) || Number(p.totalReactionsRecent || 0) >= 50;
    return {
      json: {
        publicationName: p.name || p.publicationName,
        authorName: p.authorName,
        contactEmail: email,
        substackReplyEmail: p.substackReplyEmail || null,
        publicationUrl: p.publicationUrl,
        rankingDetail: p.rankingDetail || null,
        freeSubscriberEstimate: p.freeSubscriberEstimate || null,
        monthlyPriceUsd: p.monthlyPriceUsd || null,
        totalReactionsRecent: p.totalReactionsRecent || 0,
        sponsorOutreachReady: hasSponsorSignals,
        agentSummary: p.agentSummary,
      },
    };
  });
return qualified.length ? qualified : [{ json: { totalMatched: 0, note: "No paid newsletters with direct emails matched this query." } }];
